11|int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size) {
12|#ifdef MBEDTLS_PK_PARSE_C
13|    int ret;
14|    mbedtls_pk_context pk;
15|
16|    if (Size > MAX_LEN) {
17|        //only work on small inputs
18|        Size = MAX_LEN;
19|    }
20|
21|    mbedtls_pk_init( &pk );
22|    ret = mbedtls_pk_parse_key( &pk, Data, Size, NULL, 0 );
23|    if (ret == 0) {
24|#if defined(MBEDTLS_RSA_C)
25|        if( mbedtls_pk_get_type( &pk ) == MBEDTLS_PK_RSA )
26|        {
27|            mbedtls_mpi N, P, Q, D, E, DP, DQ, QP;
28|            mbedtls_rsa_context *rsa;
29|
30|            mbedtls_mpi_init( &N ); mbedtls_mpi_init( &P ); mbedtls_mpi_init( &Q );
31|            mbedtls_mpi_init( &D ); mbedtls_mpi_init( &E ); mbedtls_mpi_init( &DP );
32|            mbedtls_mpi_init( &DQ ); mbedtls_mpi_init( &QP );
33|
34|            rsa = mbedtls_pk_rsa( pk );
35|            if ( mbedtls_rsa_export( rsa, &N, &P, &Q, &D, &E ) != 0 ) {
36|                abort();
37|            }
38|            if ( mbedtls_rsa_export_crt( rsa, &DP, &DQ, &QP ) != 0 ) {
39|                abort();
40|            }
41|
42|            mbedtls_mpi_free( &N ); mbedtls_mpi_free( &P ); mbedtls_mpi_free( &Q );
43|            mbedtls_mpi_free( &D ); mbedtls_mpi_free( &E ); mbedtls_mpi_free( &DP );
44|            mbedtls_mpi_free( &DQ ); mbedtls_mpi_free( &QP );
45|        }
46|        else
47|#endif
48|#if defined(MBEDTLS_ECP_C)
49|        if( mbedtls_pk_get_type( &pk ) == MBEDTLS_PK_ECKEY ||
50|            mbedtls_pk_get_type( &pk ) == MBEDTLS_PK_ECKEY_DH )
51|        {
52|            mbedtls_ecp_keypair *ecp = mbedtls_pk_ec( pk );
