1021|static int ssl_async_start( mbedtls_ssl_context *ssl,
1022|                            mbedtls_x509_crt *cert,
1023|                            ssl_async_operation_type_t op_type,
1024|                            mbedtls_md_type_t md_alg,
1025|                            const unsigned char *input,
1026|                            size_t input_len )
1027|{
1028|    ssl_async_key_context_t *config_data =
1029|        mbedtls_ssl_conf_get_async_config_data( ssl->conf );
1030|    unsigned slot;
1031|    ssl_async_operation_context_t *ctx = NULL;
1032|    const char *op_name = ssl_async_operation_names[op_type];
1033|
1034|    {
1035|        char dn[100];
1036|        if( mbedtls_x509_dn_gets( dn, sizeof( dn ), &cert->subject ) > 0 )
1037|            mbedtls_printf( "Async %s callback: looking for DN=%s\n",
1038|                            op_name, dn );
1039|    }
1040|
1041|    /* Look for a private key that matches the public key in cert.
1042|     * Since this test code has the private key inside Mbed TLS,
1043|     * we call mbedtls_pk_check_pair to match a private key with the
1044|     * public key. */
1045|    for( slot = 0; slot < config_data->slots_used; slot++ )
1046|    {
1047|        if( mbedtls_pk_check_pair( &cert->pk,
1048|                                   config_data->slots[slot].pk ) == 0 )
1049|            break;
1050|    }
1051|    if( slot == config_data->slots_used )
1052|    {
1053|        mbedtls_printf( "Async %s callback: no key matches this certificate.\n",
1054|                        op_name );
1055|        return( MBEDTLS_ERR_SSL_HW_ACCEL_FALLTHROUGH );
1056|    }
1057|    mbedtls_printf( "Async %s callback: using key slot %u, delay=%u.\n",
1058|                    op_name, slot, config_data->slots[slot].delay );
1059|
1060|    if( config_data->inject_error == SSL_ASYNC_INJECT_ERROR_START )
1061|    {
1062|        mbedtls_printf( "Async %s callback: injected error\n", op_name );
1063|        return( MBEDTLS_ERR_PK_FEATURE_UNAVAILABLE );
1064|    }
1065|
1066|    if( input_len > SSL_ASYNC_INPUT_MAX_SIZE )
1067|        return( MBEDTLS_ERR_SSL_BAD_INPUT_DATA );
1068|
1069|    ctx = mbedtls_calloc( 1, sizeof( *ctx ) );
1070|    if( ctx == NULL )
1071|        return( MBEDTLS_ERR_SSL_ALLOC_FAILED );
1072|    ctx->slot = slot;
1073|    ctx->operation_type = op_type;
1074|    ctx->md_alg = md_alg;
1075|    memcpy( ctx->input, input, input_len );
1076|    ctx->input_len = input_len;
1077|    ctx->remaining_delay = config_data->slots[slot].delay;
1078|    mbedtls_ssl_set_async_operation_data( ssl, ctx );
1079|
1080|    if( ctx->remaining_delay == 0 )
1081|        return( 0 );
1082|    else
1083|        return( MBEDTLS_ERR_SSL_ASYNC_IN_PROGRESS );
1084|}

